ALTER TABLE signups RENAME COLUMN src TO source;
ALTER TABLE signups ADD CONSTRAINT signups_team_fk FOREIGN KEY (team_id) REFERENCES teams(id) NOT VALID;
ALTER TABLE signups VALIDATE CONSTRAINT signups_team_fk;
DROP INDEX IF EXISTS signups_src_idx;

CREATE POLICY team_reads_own ON signups FOR SELECT TO authenticated
  USING (team_id = current_setting('app.team_id')::uuid);
